style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url('https://i.pinimg.com/736x/8a/68/03/8a6803ad0b2773ee5abd1c5c2893aa88.jpg') !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }
    
    /* This line makes the dark gray box transparent so you can see your image */
    .main-layout, .container-main, .content {
        background: transparent !important;
    }
}
